 void welcome(){LinearLayout hero=new LinearLayout(this);hero.setOrientation(1);hero.setGravity(Gravity.CENTER);hero.setPadding(dp(12),dp(38),dp(12),dp(20));TextView logo=text("AI",24,GREEN);logo.setTypeface(null,Typeface.BOLD);logo.setGravity(Gravity.CENTER);logo.setBackground(shape(dark?0xFF203D35:0xFFEAF5EF,20));hero.addView(logo,new LinearLayout.LayoutParams(dp(62),dp(62)));TextView title=text("今天想做什么？",26,INK);title.setTypeface(null,Typeface.BOLD);title.setPadding(0,dp(22),0,dp(12));hero.addView(title);TextView note=text(store.providers().length()==0?"先接入 AI，再开始你的第一个项目。":"把想法写下来，让对话一步步展开。",14,MUTED);note.setGravity(Gravity.CENTER);hero.addView(note);if(store.providers().length()==0){TextView connect=action("接入第一个 AI",true,()->providerPage("",0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(24),0,dp(6));hero.addView(connect,p);}messageList.addView(hero);for(String value:new String[]{"帮我把一个想法整理成可执行计划","和我一起梳理一个新项目","解释我接下来发给你的资料"}){TextView sample=action(value,false,()->{composer.setText(value);composer.setSelection(composer.length());});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(dp(5),dp(8),dp(5),0);messageList.addView(sample,p);}}
 void updateHeader(){if(modelLabel==null||!page.equals("chat"))return;JSONObject c=store.chat(chatId),p=c==null?null:store.provider(J.str(c,"providerId"));modelLabel.setText(p==null?"选择 AI  ▾":J.str(p,"name")+" · "+(J.str(c,"model").isEmpty()?"选择模型":J.str(c,"model"))+"  ▾");}
 void updateAttachment(){if(attachmentLabel==null)return;attachmentLabel.setVisibility(attachment==null?View.GONE:View.VISIBLE);if(attachment!=null)attachmentLabel.setText("已附加 "+J.str(attachment,"name")+" · 点击移除");}
 void updateSend(){if(sendButton==null||!page.equals("chat"))return;JSONObject active=store.active();boolean own=active!=null&&active.optString("chatId").equals(chatId);boolean enabled=own||(active==null&&composer!=null&&!composer.getText().toString().trim().isEmpty());sendButton.removeAllViews();sendButton.setBackground(shape(enabled?INK:(dark?0xFF454A50:0xFFD8DCDF),30));Icons control=new Icons(this,own?"stop":"send",BG,own?"停止生成":"发送消息");control.setOnClickListener(v->{if(own){app.engine.cancel();return;}safe(()->send());});sendButton.addView(control,new FrameLayout.LayoutParams(-1,-1));}
 void send()throws Exception{flushDraft();if(store.active()!=null||app.engine.executing()){toast("上一条回答仍在结束，请稍候或先停止");return;}JSONObject c=store.chat(chatId);if(store.provider(J.str(c,"providerId"))==null||J.str(c,"model").isEmpty()){modelPicker();return;}String value=composer.getText().toString().trim();if(value.isEmpty())return;String question=value;if(attachment!=null)question+="\n\n[附件："+J.str(attachment,"name")+"]\n"+J.str(attachment,"body");JSONObject r=store.reserve(chatId,question);attachments.remove(chatId);attachment=null;rendering=true;composer.setText("");rendering=false;main.removeCallbacks(saveDraft);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},20);Intent i=new Intent(this,ChatService.class).putExtra("requestId",J.str(r,"id"));try{if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(RuntimeException e){store.finish(J.str(r,"id"),"error",null,"无法启动回复服务，尚未主动发送请求："+e.getMessage());}chatPage();}
 static final class MessageView{JSONObject row;LinearLayout content;TextView streaming,meta;boolean formatted=false;}
 void addMessage(JSONObject m){boolean user=m.optString("role").equals("user");LinearLayout wrap=new LinearLayout(this);wrap.setOrientation(1);wrap.setPadding(0,dp(user?10:18),0,dp(user?9:16));LinearLayout bubble=new LinearLayout(this);bubble.setOrientation(1);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(user?Math.min(dp(440),getResources().getDisplayMetrics().widthPixels-dp(85)):-1,-2);if(user){bp.gravity=Gravity.RIGHT;bubble.setPadding(dp(16),dp(12),dp(16),dp(8));bubble.setBackground(shape(SURFACE,20));}else{JSONObject meta=m.optJSONObject("meta");TextView by=text("●  "+(meta==null?"AI":meta.optString("provider","AI"))+"  ·  "+(meta==null?"":meta.optString("model","")),11,MUTED);by.setMaxLines(1);by.setEllipsize(TextUtils.TruncateAt.END);by.setPadding(0,0,0,dp(10));bubble.addView(by);}LinearLayout content=new LinearLayout(this);content.setOrientation(1);bubble.addView(content,new LinearLayout.LayoutParams(-1,-2));MessageView v=new MessageView();v.row=m;v.content=content;v.meta=text("",11,MUTED);v.meta.setPadding(0,dp(8),0,0);bubble.addView(v.meta);messageViews.put(J.str(m,"id"),v);updateMessage(v,m);bubble.setOnLongClickListener(w->{messageActions(v.row);return true;});wrap.addView(bubble,bp);messageList.addView(wrap);}
 void updateMessage(MessageView v,JSONObject m){String state=m.optString("state"),value=m.optString("body");boolean streaming=state.equals("queued")||state.equals("streaming");v.row=m;if(streaming){if(v.streaming==null){v.content.removeAllViews();v.streaming=Markdown.base(v.content,INK);v.content.addView(v.streaming);}v.streaming.setText(value.isEmpty()?(state.equals("queued")?"准备回复…":"正在等待服务商回复…"):value);v.meta.setText("正在生成 · 可停止");v.formatted=false;}else if(!v.formatted){Markdown.render(v.content,value.isEmpty()?"未获得文字回复":value,INK,MUTED,SURFACE);JSONObject meta=m.optJSONObject("meta");String note=meta==null?"":J.str(meta,"error");if(note.isEmpty()&&m.optString("role").equals("assistant"))note="复制  ·  详情";v.meta.setText(note);v.meta.setTextColor(state.equals("done")?MUTED:RED);v.meta.setOnClickListener(w->messageActions(v.row));v.formatted=true;}}
 @Override public void changed(String changed,boolean finished){if(!page.equals("chat"))return;if(chatId.equals(changed)){boolean bottom=messageScroll.getChildAt(0).getHeight()-messageScroll.getScrollY()-messageScroll.getHeight()<dp(140);JSONObject last=store.lastMessage(chatId);if(last!=null){MessageView v=messageViews.get(J.str(last,"id"));if(v!=null)updateMessage(v,last);}if(bottom)messageScroll.post(()->messageScroll.fullScroll(View.FOCUS_DOWN));}updateSend();}
 void copy(String value){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("AI工作台",value));toast("已复制");}
 void messageActions(JSONObject m){String[] choices=m.optString("role").equals("assistant")?new String[]{"复制回答","查看请求与用量","把“继续”放入输入框"}:new String[]{"复制消息","放回输入框修改"};new AlertDialog.Builder(this).setItems(choices,(dialog,n)->safe(()->{if(n==0)copy(m.optString("body"));else if(m.optString("role").equals("assistant")&&n==1){JSONObject meta=m.optJSONObject("meta"),r=meta==null?null:store.request(J.str(meta,"requestId"));if(r==null)alert(J.pretty(meta));else{JSONObject d=r.getJSONObject("data");alert("状态："+r.optString("status")+"\n服务地址："+d.optString("endpoint")+"\n模型："+d.optString("model")+"\n结束原因："+d.optString("finishReason")+"\n用量："+J.pretty(d.optJSONObject("usage"))+"\n"+d.optString("error",""));}}else{composer.setText(m.optString("role").equals("user")?m.optString("body"):"继续");composer.setSelection(composer.length());}})).show();}
