 void fetchModels(ProviderForm f)throws Exception{if(f.loading)return;JSONObject p=gatherForm(f,true);String key=J.str(p,"apiKey");if(key.isEmpty())key=KeyVault.open(J.str(p,"keyCipher"));J.require(!key.isEmpty(),"请先填写 API Key");final String token=key;final long generation=epoch;f.loading=true;f.feedback.setText("正在读取模型列表…");localIo.execute(()->{try{List<String> names=new ApiClient().models(p,token);main.post(()->{f.loading=false;if(epoch!=generation||form!=f)return;LinkedHashSet<String> all=new LinkedHashSet<>();for(String value:f.models.getText().toString().split("[\\n,，]"))if(!value.trim().isEmpty())all.add(value.trim());all.addAll(names);StringBuilder s=new StringBuilder();for(String value:all){if(s.length()>0)s.append('\n');s.append(value);}f.models.setText(s);f.feedback.setText("已读取 "+names.size()+" 个模型。请选择支持文字聊天的模型；保存后在聊天顶部切换。");});}catch(Exception e){main.post(()->{f.loading=false;if(epoch==generation&&form==f)f.feedback.setText("读取失败："+e.getMessage()+"\n可手动填写模型ID，输入已保留。");});}});}


 void pickText(boolean project){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"text/plain","text/markdown","text/x-markdown"});startActivityForResult(i,project?41:42);}
 String filename(Uri uri){try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception ignored){}return "参考文本.txt";}
 String readText(Uri uri)throws Exception{byte[] data;try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){J.require(out.size()+n<=2400000,"文件超过2.4MB，请选较小的TXT或Markdown");out.write(b,0,n);}data=out.toByteArray();}try{return Charset.forName("UTF-8").newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(data)).toString().replaceFirst("^\\uFEFF","");}catch(CharacterCodingException e){return Charset.forName("GB18030").newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(data)).toString();}}
 void export(String filename,String mime,byte[] value){exportBytes=value;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(i,43);}
 void exportChat()throws Exception{JSONObject c=store.chat(chatId);StringBuilder value=new StringBuilder("# "+c.optString("title")+"\n\n");JSONArray ms=store.messages(chatId);for(int i=0;i<ms.length();i++){JSONObject m=ms.getJSONObject(i),meta=m.optJSONObject("meta");value.append("## ").append(m.optString("role").equals("user")?"我":meta==null?"AI":meta.optString("provider","AI")+" · "+meta.optString("model")).append("\n\n").append(m.optString("body")).append("\n\n");if(!m.optString("state").equals("done"))value.append("[状态：").append(m.optString("state")).append("]\n\n");}export("AI工作台-对话.md","text/markdown",value.toString().getBytes("UTF-8"));}
