 @Override protected void onActivityResult(int code,int result,Intent intent){super.onActivityResult(code,result,intent);if(result!=RESULT_OK||intent==null||intent.getData()==null)return;Uri uri=intent.getData();if(code==43){safe(()->{if(exportBytes==null)return;try(OutputStream out=getContentResolver().openOutputStream(uri)){out.write(exportBytes);}exportBytes=null;toast("已导出");});return;}if(code==41||code==42){final String target=code==41?pickedProject:chatId;String name=filename(uri);localIo.execute(()->{try{String value=readText(uri);main.post(()->{if(isFinishing()||isDestroyed())return;new AlertDialog.Builder(this).setTitle("添加 "+name).setMessage(value.length()+"字符\n\n"+value.substring(0,Math.min(400,value.length()))).setNegativeButton("取消",null).setPositiveButton(code==41?"加入项目":"附加到消息",(d,n)->safe(()->{if(code==41){store.addFile(target,name,value);projectPage(target);}else if(chatId.equals(target)){attachment=J.obj("name",name,"body",value);attachments.put(target,attachment);if(!page.equals("chat"))chatPage();updateAttachment();}else alert("对话已切换，请返回原对话再附加文件。");})).show();});}catch(Exception e){main.post(()->alert("读取失败："+e.getMessage()));}});}if(code==44){localIo.execute(()->{try{JSONObject backup;try(InputStream in=getContentResolver().openInputStream(uri)){backup=new JSONObject(ApiClient.read(in,64000000));}main.post(()->{if(isFinishing()||isDestroyed())return;new AlertDialog.Builder(this).setTitle("导入 AI 工作台备份").setMessage("将合并新增项目、对话与文件。已有相同ID的记录保留，不覆盖。密钥不导入，任务不会自动恢复。").setNegativeButton("取消",null).setPositiveButton("导入",(d,n)->safe(()->{int count=store.restore(backup);alert("已导入 "+count+" 条新增记录。API Key需在设置重新填写。");})).show();});}catch(Exception e){main.post(()->alert("导入失败，原数据保留："+e.getMessage()));}});}}

